#include <map>
#include <set>

int main() {
    std::map<int, double> m = {{1, 10.0}};
    std::set<int> s = {5};

    // Map value_type is std::pair<const int, double>
    auto map_it = m.begin();
    map_it->second = 20.0; // OK: Value is mutable
    // map_it->first = 2; // ERROR: Key is const

    // Set value_type is const int
    auto set_it = s.begin();
    // *set_it = 6; // ERROR: Element is const

    return 0;
}
